/**
 * Static catalog (build-time snapshot).
 *
 * `search-index.static.json` is generated by `scripts/build-search-index.mjs`
 * (npm prebuild) from the same bounded curated groups the server serves. The
 * running application seeds its catalog + element-set caches from here, which
 * is why search and detail for curated objects answer instantly on a cold
 * server instance instead of paying a chain of throttled provider fetches.
 *
 * Honesty: these are real element sets fetched from CelesTrak at build time -
 * a form of "cached" data. Freshness never lies in responses: hydrated
 * entries age from the snapshot's generatedAt and are served with the normal
 * cache/stale lineage labels, and every mutation-capable path still attempts
 * the live provider first where freshness matters (see SatelliteService).
 */

import staticIndexFile from "./search-index.static.json";
import { parseTle } from "@/domain/orbit/tle";
import type { TwoLineElementSet } from "@/domain/orbit/types";

interface StaticIndexFile {
  generatedAt: string;
  gaps: string | null;
  entries: {
    satelliteNumber: string;
    name: string;
    group: string;
    tleLine1: string;
    tleLine2: string;
  }[];
}

const data = staticIndexFile as StaticIndexFile;

export interface StaticCatalogEntry {
  satelliteNumber: string;
  name: string;
  group: string;
  generatedAt: Date;
  elementSet: TwoLineElementSet;
}

let memoized: StaticCatalogEntry[] | null = null;
let memoizedGeneratedAt: Date | null = null;

/**
 * Snapshot of build-time catalog data. Parsed once per process; malformed
 * rows are skipped (support robustness), never thrown.
 */
export function loadStaticCatalog(): { generatedAt: Date | null; entries: StaticCatalogEntry[] } {
  if (memoized) return { generatedAt: memoizedGeneratedAt, entries: memoized };
  const entries: StaticCatalogEntry[] = [];
  const generatedAt = data.generatedAt ? new Date(data.generatedAt) : null;
  for (const row of data.entries) {
    try {
      const elementSet = parseTle(row.tleLine1, row.tleLine2, row.name);
      entries.push({
        satelliteNumber: elementSet.satelliteNumber,
        name: row.name,
        group: row.group,
        generatedAt: generatedAt ?? new Date(),
        elementSet,
      });
    } catch {
      // Malformed snapshot row: skip it - the live provider path remains.
    }
  }
  memoized = entries;
  memoizedGeneratedAt = generatedAt;
  return { generatedAt, entries };
}

export function staticCatalogGaps(): string | null {
  return data.gaps;
}

/** Snapshot time for provenance honesty (null when no snapshot data). */
export function staticCatalogGeneratedAt(): Date | null {
  return loadStaticCatalog().generatedAt;
}
